-- 0101: RLS policies. GENERATED by scripts/build-policies.sh from packages/db/policies/*.sql.
-- Do not edit: change the per-table file and run `pnpm policies:build`.

-- ---- assets ----
create policy assets_select on public.assets for select to authenticated
  using (case when project_id is null then eduai.is_org_admin(org_id) else eduai.can_access_project(project_id) end);
-- users upload; generated/rendered assets come from the orchestrator (service role)
create policy assets_insert on public.assets for insert to authenticated
  with check (project_id is not null and eduai.can_access_project(project_id)
              and source = 'uploaded' and created_by = auth.uid());
-- immutable: no update/delete

-- ---- assistant_events ----
create policy assistant_events_select on public.assistant_events for select to authenticated
  using (user_id = auth.uid() or (cohort_id is not null and eduai.can_manage_cohort(cohort_id)));
-- written by the orchestrator's /assist/* under service role

-- ---- bible_entries ----
create policy bible_entries_select on public.bible_entries for select to authenticated
  using (eduai.can_access_project(project_id));
create policy bible_entries_insert on public.bible_entries for insert to authenticated
  with check (eduai.can_access_project(project_id) and created_by = auth.uid());
create policy bible_entries_update on public.bible_entries for update to authenticated
  using (eduai.can_access_project(project_id)) with check (eduai.can_access_project(project_id));
create policy bible_entries_delete on public.bible_entries for delete to authenticated
  using (eduai.can_access_project(project_id));

