-- ---- invites ----
create policy invites_select on public.invites for select to authenticated
  using (eduai.is_org_admin(org_id));
create policy invites_insert on public.invites for insert to authenticated
  with check (eduai.can_grant_role(org_id, role) and invited_by = auth.uid());
create policy invites_update on public.invites for update to authenticated
  using (eduai.is_org_admin(org_id) and accepted_at is null)
  with check (eduai.can_grant_role(org_id, role));
create policy invites_delete on public.invites for delete to authenticated
  using (eduai.is_org_admin(org_id) and accepted_at is null);
-- acceptance runs through eduai.accept_invite under service role

-- ---- job_events ----
create policy job_events_select on public.job_events for select to authenticated
  using (exists (select 1 from public.jobs j where j.id = job_id and eduai.can_access_project(j.project_id)));
-- append-only, written by eduai.* functions

-- ---- job_receipts ----
create policy job_receipts_select on public.job_receipts for select to authenticated
  using (exists (select 1 from public.jobs j where j.id = job_id and eduai.can_access_project(j.project_id)));
-- written once by eduai.settle_job

-- ---- jobs ----
create policy jobs_select on public.jobs for select to authenticated
  using (eduai.can_access_project(project_id));
-- org_id / cohort_id / provider are filled by the eduai.jobs_fill_defaults trigger before this check
create policy jobs_insert on public.jobs for insert to authenticated
  with check (eduai.can_access_project(project_id) and requested_by = auth.uid() and status = 'queued');
-- the only user-side transition: cancel while still queued
create policy jobs_cancel on public.jobs for update to authenticated
  using (requested_by = auth.uid() and status = 'queued')
  with check (requested_by = auth.uid() and status = 'cancelled');

-- ---- ledger ----
create policy ledger_select on public.ledger for select to authenticated
  using ((project_id is not null and eduai.can_access_project(project_id))
         or user_id = auth.uid()
         or eduai.can_manage_cohort(cohort_id));
-- append-only, written by eduai.* functions under service role

